// ---------------------------------------------------------------- questions (appointment sheet, prep pack, decision pages)
/**
 * Settings match the ten decision rows word for word (src/lib/decisions.ts appends hand-written questions to the
 * section whose setting matches), plus "Newly diagnosed", the five appointment types and carers.
 */
export const colorectalQuestions: Question[] = [
  // Newly diagnosed
  { setting: "Newly diagnosed", question: "Who is my clinical nurse specialist, and what is the 24-hour number for the team?", why: "The NHS says a specialist treatment team explains the treatments and helps you manage side effects; every urgent card on this page starts with ringing that number, so it is the first thing to write down." },
  { setting: "Newly diagnosed", question: "Is my cancer in the colon, the rectum, or both, and what stage and grade is it?", why: "Bowel Cancer UK puts the stage and grade first on its list of questions; the NHS says treatment depends on whether the cancer is in the colon or rectum, because rectal cancer often has radiotherapy and colon cancer usually does not." },
  { setting: "Newly diagnosed", question: "Has my case been to the multidisciplinary team meeting yet, and how will I hear what was agreed?", why: "Macmillan says a team of specialists meets to plan your treatment; NICE NG151 asks for information on all treatment options available to you, including the benefits, risks and side effects." },
  { setting: "Newly diagnosed", question: "Have the tumour tests been sent: mismatch repair or microsatellite instability, RAS, BRAF, and Lynch syndrome testing?", why: "NICE NG151 says to test for RAS and BRAF V600E in everyone with metastatic colorectal cancer suitable for systemic treatment and points to its guidance on molecular testing strategies for Lynch syndrome; Macmillan explains what the tests on the cancer cells look for." },
  { setting: "Newly diagnosed", question: "Am I likely to need a stoma, and if so is it temporary or permanent?", why: "NICE NG151 says to tell people the likelihood of having a stoma, why it might be necessary and for how long it might be needed; Bowel Cancer UK says the surgeon may not know for certain until the operation has started." },
  { setting: "Newly diagnosed", question: "Is there a prehabilitation service here, and what should I be doing in the weeks before treatment?", why: "Bowel Cancer UK says prehabilitation improves your physical and emotional health before treatment and can reduce complications and time in hospital; Cancer Research UK describes the exercise, diet, smoking and wellbeing parts." },
  { setting: "Newly diagnosed", question: "Will treatment affect my fertility, and can I see a fertility specialist before it starts?", why: "Bowel Cancer UK says some treatments for bowel cancer affect fertility and your healthcare team should discuss the risk when you are diagnosed; pelvic radiotherapy will often cause infertility and early menopause." },

  // The operation and the stoma
  { setting: S_SURGERY, question: "Which operation are you proposing, how much bowel comes out, and will it be keyhole or open?", why: "NICE NG151 recommends laparoscopic resection as an alternative to open resection for colon and for rectal cancer when both are suitable, and says to consider open surgery for locally advanced tumours or after previous abdominal or pelvic surgery." },
  { setting: S_SURGERY, question: "If I need a stoma, will it be a colostomy or an ileostomy, and how long before it could be reversed?", why: "Bowel Cancer UK says a reversible stoma is formed to let the bowel heal and a permanent one is formed when the two ends cannot be joined; Cancer Research UK says the reversal usually happens after treatment finishes, so the timing is different for everyone." },
  { setting: S_SURGERY, question: "Can I meet the stoma care nurse before the operation, and will the site be marked?", why: "Bowel Cancer UK says you meet the stoma care specialist nurse before the operation, they show you the equipment and may mark the spot on your abdomen; NICE NG151 says a trained stoma professional should provide information on care and on living with a stoma." },
  { setting: S_SURGERY, question: "How many of these operations does this unit and this surgeon do each year?", why: "NICE NG151 says hospitals performing major resection for rectal cancer should perform at least 10 each year and individual surgeons at least 5; you are allowed to ask." },
  { setting: S_SURGERY, question: "What are the risks of this operation for me, including an anastomotic leak, and what is the enhanced recovery plan?", why: "NICE NG151 lists anastomotic leak, pelvic abscess, bleeding, hernia and urinary retention among the complications of total mesorectal excision, and says to explain what recovery protocols such as enhanced recovery after surgery involve and their value." },

  // Chemotherapy after surgery
  { setting: S_ADJUVANT, question: "What is the actual number: how much does chemotherapy after surgery change my chance of the cancer coming back?", why: "NICE NG151 asks teams to base the choice on the person's histopathology, performance status, personal preferences, any comorbidities and age, which is a conversation about absolute benefit rather than a rule." },
  { setting: S_ADJUVANT, question: "Three months of CAPOX or six months of a single tablet: which are you recommending for me, and why?", why: "NICE NG151 offers capecitabine with oxaliplatin for 3 months for stage 3 disease, or if that is not suitable either FOLFOX for 3 to 6 months or a single-agent fluoropyrimidine such as capecitabine for 6 months." },
  { setting: S_ADJUVANT, question: "My cancer is stage 2. Does the guideline recommend chemotherapy for me at all, and what are the risk features you are weighing?", why: "NICE NG151 makes an adjuvant recommendation for stage 3 colon and rectal cancer and makes none for stage 2, so this is a discussion about individual risk features rather than a guideline rule." },
  { setting: S_ADJUVANT, question: "Has my tumour been tested for mismatch repair, and does that change whether chemotherapy helps me?", why: "Macmillan explains that tests on the bowel cancer cells look for mismatch repair and microsatellite instability, which affect treatment choices; ask what your result means for the decision in front of you." },
  { setting: S_ADJUVANT, question: "Will you use a ctDNA blood test to help decide, and is that inside a trial?", why: "Circulating tumour DNA after surgery is being tested as a way to add or withhold chemotherapy (DYNAMIC and the other ctDNA-guided studies listed under this cancer); ask whether it is available to you and whether it changes the plan or only the information." },
  { setting: S_ADJUVANT, question: "I already have tingling in my fingers. Should oxaliplatin be reduced or left out?", why: "NICE NG151 says to emphasise the importance of monitoring and managing side effects during non-surgical treatment to try to prevent permanent damage, giving prolonged sensory symptoms after platinum chemotherapy as the example that should prompt a dose reduction." },
  { setting: S_ADJUVANT, question: "When does chemotherapy need to start after my operation, and what happens if I am still recovering?", why: "Recovery from bowel surgery and the start of chemotherapy have to be balanced; Macmillan explains that chemotherapy after surgery aims to reduce the risk of the cancer coming back, and your team can say how long a delay is acceptable." },

  // Rectal cancer: order of treatment
  { setting: S_RECTAL_ORDER, question: "Am I being offered short-course radiotherapy or long-course chemoradiotherapy, and what is the difference for me?", why: "NICE NG151 says to offer preoperative radiotherapy or chemoradiotherapy to people with rectal cancer that is cT1 to T2 with node involvement, or cT3 to T4 with any node status, and Macmillan explains what chemoradiation involves week by week." },
  { setting: S_RECTAL_ORDER, question: "If the tumour disappears on the scan and at examination, can I defer surgery and be watched instead?", why: "NICE NG151 says to inform people with a complete clinical and radiological response who wish to defer surgery that there is a risk of recurrence and there are no prognostic factors to guide selection, and to encourage participation in a clinical trial with data collected via a national registry." },
  { setting: S_RECTAL_ORDER, question: "If I choose watch and wait, exactly how often will I be examined and scanned, and what happens if it regrows?", why: "Deferral of surgery is a follow-up commitment, not the end of treatment; NICE NG151 asks for registry data collection, so ask which registry and which schedule you are being enrolled on." },
  { setting: S_RECTAL_ORDER, question: "How likely am I to need a permanent stoma with each of these orders of treatment?", why: "NICE NG151's own table for early rectal cancer compares transanal excision, endoscopic submucosal dissection and total mesorectal excision on exactly this point, including whether a stoma is needed and the effect on bowel and sexual function." },
  { setting: S_RECTAL_ORDER, question: "What will radiotherapy to the pelvis do to my bowel, bladder and sexual function in the long run?", why: "Macmillan says bowel side effects of pelvic radiotherapy may keep getting worse for a few weeks after treatment before improving, and that some do not completely go away; these are called late effects and should always be reported." },

  // First-line metastatic
  { setting: S_FIRST_LINE, question: "What are my RAS, BRAF and mismatch repair results, and which side of the bowel did the cancer start on?", why: "NICE NG151 says to test for RAS and BRAF V600E mutations in all people with metastatic colorectal cancer suitable for systemic anticancer treatment; the result decides whether the EGFR antibodies can be used at all." },
  { setting: S_FIRST_LINE, question: "Is the aim of this treatment to shrink the cancer enough for an operation, or to control it?", why: "Bowel Cancer UK separates treatment that aims to control advanced bowel cancer from treatment given to make surgery possible; the answer changes how much side effect is worth accepting." },
  { setting: S_FIRST_LINE, question: "If I am RAS wild-type, are you adding cetuximab or panitumumab, and what will the rash be like?", why: "NICE NG151 recommends cetuximab with FOLFOX or FOLFIRI for untreated RAS wild-type metastatic disease that also expresses EGFR (1.5.3), and panitumumab with the same chemotherapy for untreated RAS wild-type disease with no EGFR requirement (1.5.4); Macmillan says the acne-like rash on the face, neck, chest and back is most likely to start in the first 2 or 3 weeks." },
  { setting: S_FIRST_LINE, question: "What is the plan for a treatment break or maintenance once the cancer is under control?", why: "Bowel Cancer UK has a page on taking a break from treatment; long courses of oxaliplatin cause cumulative nerve damage, so when to stop and what to continue is a decision worth making in advance." },
  { setting: S_FIRST_LINE, question: "Should my primary tumour be removed even though it is not causing symptoms?", why: "NICE NG151 says to consider surgical resection of the primary tumour for people with incurable metastatic disease receiving systemic therapy who have an asymptomatic primary tumour, and gives a table of advantages and disadvantages to share." },

  // Liver
  { setting: S_LIVER, question: "Has a liver surgeon looked at my scans, and is an operation possible now or after chemotherapy?", why: "NICE NG151 says to consider resection, either simultaneous or sequential, after discussion by a multidisciplinary team with expertise in resection of disease in all involved sites, and to consider perioperative systemic therapy if liver resection is suitable." },
  { setting: S_LIVER, question: "If surgery is not possible, is ablation or stereotactic radiotherapy an option for me?", why: "NICE NG151 says to consider chemotherapy with local ablative techniques for colorectal liver metastases unsuitable for resection after discussion by a specialist multidisciplinary team, and considers metastasectomy, ablation or stereotactic body radiation therapy for lung metastases." },
  { setting: S_LIVER, question: "Would a second opinion from a specialist liver unit change what is possible?", why: "Bowel Cancer UK has a page on getting a second opinion; liver units differ in what they will attempt, and NICE asks for a team with expertise in resection of disease in all involved sites." },
  { setting: S_LIVER, question: "What would recovery from a liver operation look like alongside my bowel surgery?", why: "NICE NG151 allows both simultaneous and sequential resection; the two orders have very different recoveries, so ask which is proposed and why." },

  // Immunotherapy
  { setting: S_IMMUNOTHERAPY, question: "Is my tumour mismatch repair deficient or MSI-high, and what does that mean for immunotherapy?", why: "NICE NG151 recommends nivolumab with ipilimumab and pembrolizumab for untreated metastatic colorectal cancer with high microsatellite instability or mismatch repair deficiency, so the test result is the gateway to the treatment." },
  { setting: S_IMMUNOTHERAPY, question: "How long would immunotherapy continue, and what happens when it stops?", why: "NICE NG151 says pembrolizumab should be stopped after 2 years or earlier if disease progresses; ask what the plan is at that point." },
  { setting: S_IMMUNOTHERAPY, question: "Which immune side effects would make me ring you the same day?", why: "Immune reactions can start at any time and for months after the last dose; the red cards on this page list diarrhoea, breathlessness, yellow eyes, severe tiredness and new diabetes as same-day calls." },
  { setting: S_IMMUNOTHERAPY, question: "If my cancer is mismatch repair deficient and has not spread, is immunotherapy before surgery an option or a trial here?", why: "The record carries the trials of immunotherapy before surgery in mismatch repair deficient colon and rectal cancer (NICHE-2 and AZUR-1); NICE NG151 does not recommend it outside those settings, so ask whether a trial is open to you." },

  // Later lines
  { setting: S_LATER_LINES, question: "What is left after this line, and in which order would you use it?", why: "NICE NG151 lists trifluridine with tipiracil and bevacizumab after 2 systemic treatments, fruquintinib if that combination is not suitable, regorafenib and trifluridine with tipiracil alone; knowing the sequence in advance makes each decision less sudden." },
  { setting: S_LATER_LINES, question: "How will we know whether this line is working, and when would we stop?", why: "Bowel Cancer UK has a page on taking a break from treatment and on treating advanced bowel cancer; agreeing the scan interval and the stopping rule in advance protects the time you have." },
  { setting: S_LATER_LINES, question: "Is there a trial for me at this point, and should I be referred before I am less well?", why: "The NHS says clinical trials test new treatments and that you can ask your doctor whether one is suitable; trials usually need you to be well enough to take part, so the referral is easier earlier than later." },
  { setting: S_LATER_LINES, question: "If I decide to stop anti-cancer treatment, what care continues?", why: "Bowel Cancer UK says palliative care may start when you are diagnosed with advanced bowel cancer or after treatment has stopped working, and that its aim is to improve quality of life." },

  // Lynch
  { setting: S_LYNCH, question: "Has my tumour been tested for mismatch repair, and has MLH1 promoter methylation been checked before genetic testing?", why: "Mismatch repair loss can be sporadic rather than inherited; the methylation test separates the two, and Bowel Cancer UK says testing for Lynch syndrome should be offered at diagnosis because the condition can affect treatment options." },
  { setting: S_LYNCH, question: "If I have Lynch syndrome, who in my family should be tested, and who arranges it?", why: "Bowel Cancer UK says Lynch syndrome runs in families, so if a person has it there is a 50 percent chance their children, brothers and sisters also have it, and family members of patients who test positive should be offered the same genetic tests." },
  { setting: S_LYNCH, question: "What surveillance would I have with Lynch syndrome, and how often?", why: "Bowel Cancer UK says people with Lynch syndrome should be in a surveillance programme with regular colonoscopy every 18 months to two years, which can reduce the chance of dying from bowel cancer by as much as 72 percent." },
  { setting: S_LYNCH, question: "Should I be taking aspirin, and at what dose?", why: "NICE NG151 says to consider aspirin, taken daily and for a period of more than 2 years, to reduce the risk of colorectal cancer in people with Lynch syndrome, and notes that in January 2020 this was an off-label use with a NICE patient decision aid to support the discussion." },
  { setting: S_LYNCH, question: "Where does the genetic result go, and what do I need to tell an insurer or employer?", why: "The NHS explains how genetic and genomic testing works and who sees the result; Bowel Cancer UK's work and money page sets out the Equality Act protections at work." },

  // Trial or standard
  { setting: S_TRIAL, question: "Is there a trial open to me now, here or at another hospital, and what would it involve?", why: "Bowel Cancer UK says some trials test new treatments and others test new ways of using existing treatments, and that you should ask your healthcare team whether you are suitable for any current trials in your area; the NHS says you can ask your doctor or a patient organisation about trials you may be eligible to join." },
  { setting: S_TRIAL, question: "If I join, can I leave, and would standard treatment still be available afterwards?", why: "The NHS says you can choose to leave at any point without giving a reason and without it affecting the care you receive." },
  { setting: S_TRIAL, question: "What extra visits, scans or biopsies would the trial need, and are travel costs covered?", why: "Bowel Cancer UK's page on trials and its work, money and travel page together cover the practical cost of taking part, which is a fair part of the decision." },

  // Palliative care
  { setting: S_PALLIATIVE, question: "Can I be referred to the palliative care team now, alongside my treatment, rather than later?", why: "Bowel Cancer UK says palliative care may start when you are diagnosed with advanced bowel cancer, and a randomised trial (Temel 2010) found early palliative care alongside cancer treatment improved quality of life and mood." },
  { setting: S_PALLIATIVE, question: "Who do I ring out of hours when pain or sickness gets out of control at home?", why: "Marie Curie explains what palliative care covers and who provides it; the NHS says the symptom control or palliative care team helps you manage symptoms and supports your loved ones." },
  { setting: S_PALLIATIVE, question: "Where would I prefer to be cared for, and how do I record that?", why: "Bowel Cancer UK says you can choose where you would prefer to receive care and where you wish to die, and that your choices can be documented by your healthcare team and kept with your medical records." },
  { setting: S_PALLIATIVE, question: "What support is there for my family and for any children at home?", why: "Bowel Cancer UK says end of life care also includes support and practical help for your family and carers, and Macmillan has information for people supporting someone with cancer." },

  // Appointment types
  { setting: "Surgeon appointment", question: "Draw me what you are taking out and what you are joining back together.", why: "Macmillan's pages on surgery for colon and rectal cancer describe the resections in words; a drawing turns an anterior resection or a right hemicolectomy into something you can repeat to your family." },
  { setting: "Surgeon appointment", question: "What is my risk of a leak at the join, and what would the first sign be?", why: "NICE NG151 lists anastomotic leak among the complications of total mesorectal excision; knowing the first sign shortens the time to treatment." },
  { setting: "Surgeon appointment", question: "How long in hospital, how long before I drive, and how long before I lift anything?", why: "The NHS says it usually takes around 8 weeks to recover from a colostomy, to avoid strenuous activity or heavy lifting for 8 weeks while the tummy muscles heal, and to wait until you have recovered before driving." },
  { setting: "Surgeon appointment", question: "Will you be taking at least 12 lymph nodes, and when will I get the pathology report?", why: "NICE NG151's table says removing lymph nodes gives more accurate staging and a better chance of cure; the pathology report is what the chemotherapy decision is made on." },

  { setting: "Oncologist appointment", question: "What is this chemotherapy for: cure, control or symptoms, and over what period?", why: "NICE NG151 says to give people information on all treatment options including the potential benefits, risks, side effects and implications, so that aim should be said out loud." },
  { setting: "Oncologist appointment", question: "Have I had the DPD blood test before fluorouracil or capecitabine?", why: "Macmillan says you should have a blood test before capecitabine to check for gene changes affecting DPD, because low DPD raises the risk of serious or life-threatening side effects." },
  { setting: "Oncologist appointment", question: "Which side effects should make me ring the 24-hour line, and which can wait?", why: "Macmillan's drug pages set the thresholds: a temperature the team specifies, diarrhoea that anti-diarrhoea drugs have not settled within 24 hours, unexplained bruising or bleeding, and any skin blistering." },
  { setting: "Oncologist appointment", question: "How will we measure whether it is working, and when is the first scan?", why: "Agreeing the scan interval in advance turns a wait into a plan; NICE NG151 asks for information on why a treatment plan might need to change during care." },
  { setting: "Oncologist appointment", question: "What is my follow-up after treatment, and does it include CEA blood tests and CT scans?", why: "NICE NG151 says to offer follow-up for detection of local recurrence and distant metastases for the first 3 years, including serum carcinoembryonic antigen and CT of the chest, abdomen and pelvis." },

  { setting: "Stoma nurse appointment", question: "Show me how to change the bag, and watch me do it once before I go home.", why: "Cancer Research UK says the stoma nurse teaches you to manage the stoma while you are in hospital and that it may help for a close family member to be there too." },
  { setting: "Stoma nurse appointment", question: "One-piece or two-piece, drainable or closed: which suits my stoma and my day?", why: "The NHS describes the two main types of bag and says how often you change it varies between people, so you will soon find what works for you." },
  { setting: "Stoma nurse appointment", question: "How do I order supplies on prescription, and do I get free prescriptions?", why: "The NHS says that with a permanent colostomy your GP gives you a prescription to order stoma bags for free on the NHS, and that with a temporary colostomy you may need to pay; Colostomy UK explains how to order supplies." },
  { setting: "Stoma nurse appointment", question: "What is a blockage, what does it feel like, and who do I ring?", why: "The NHS says if less poo is coming out than usual or the stoma stops producing poo you may have a blockage, that a blockage is serious because the bowel could burst, and to speak to your stoma nurse urgently with cramps, sickness or swelling around the stoma." },
  { setting: "Stoma nurse appointment", question: "Which foods block an ileostomy, and how much should I be drinking?", why: "Cancer Research UK says celery, tough fruit skins, nuts and mushrooms may cause a blockage with an ileostomy, that you lose more fluid through an ileostomy, and that your wee should be a pale straw colour through the day." },
  { setting: "Stoma nurse appointment", question: "What about sore skin, a hernia around the stoma, swimming, and clothes?", why: "The NHS lists hernia, retraction, prolapse and skin damage as stoma problems the nurse can help with; Cancer Research UK says all sorts of physical activities are possible, including swimming." },
  { setting: "Stoma nurse appointment", question: "Can I have a RADAR key and a Just Can't Wait card?", why: "Macmillan points to the Bladder and Bowel Community's Just Can't Wait card for quicker access to a toilet; Colostomy UK explains the RADAR key scheme for accessible toilets." },

  { setting: "Genomics appointment", question: "Which test is this: a test on the tumour, or a blood test for an inherited change?", why: "The NHS explains the difference between genetic and genomic testing and what each can show; Macmillan explains the tests done on bowel cancer cells." },
  { setting: "Genomics appointment", question: "What are the possible results, including one that is uncertain, and what would each mean?", why: "A variant of uncertain significance is a common outcome and changes nothing on its own; asking in advance prevents a frightening letter later." },
  { setting: "Genomics appointment", question: "How long will the result take, and will it change my treatment or only my family's screening?", why: "Bowel Cancer UK says Lynch syndrome testing should be offered at diagnosis because the condition can affect treatment options, and that family members should then be offered the same tests." },
  { setting: "Genomics appointment", question: "If the result is positive, how are my relatives contacted and supported?", why: "Bowel Cancer UK calls this cascade testing and says finding the undiagnosed relatives is how life-saving surveillance reaches them." },

  { setting: "Palliative care appointment", question: "What can you help with that my cancer team cannot?", why: "Marie Curie explains that palliative care covers symptom control, emotional, spiritual and practical support, for you and for the people close to you, at any stage of an illness." },
  { setting: "Palliative care appointment", question: "Can we write down what matters most to me, and who should be asked if I cannot speak?", why: "Bowel Cancer UK says putting plans in place can be documented by your healthcare team and kept with your medical records so your loved ones know how you would like to be cared for." },
  { setting: "Palliative care appointment", question: "What is available at home, in a hospice and in hospital, and how quickly?", why: "Bowel Cancer UK says you may be able to have care at home, in a hospice, in hospital or in a care home, and that hospices offer day visits as well as stays." },
  { setting: "Palliative care appointment", question: "What help is there with money, benefits and equipment at home?", why: "Bowel Cancer UK's work, money and travel page lists the benefits that may apply; Macmillan's welfare rights advisers work out what you can claim." },

  // Carers
  { setting: "For carers", question: "What should I watch for at home, and what is the number I ring first?", why: "Bowel Cancer UK says one of the best ways to help is to learn about the symptoms and who to ask for help; every red card here starts with the hospital's 24-hour number." },
  { setting: "For carers", question: "Can I come to appointments and write down what is said?", why: "Bowel Cancer UK says some people find it useful to take someone with them to medical appointments to help take notes and remind them what was discussed." },
  { setting: "For carers", question: "Am I entitled to a carer's assessment and to carer's benefits?", why: "The NHS says a carer's assessment is free, is for anyone over 18 looking after another adult, and is separate from the assessment of the person you care for; it also lists the benefits carers may be able to claim." },
  { setting: "For carers", question: "Who supports me, and what do I do when I cannot cope?", why: "Bowel Cancer UK has a page on taking care of yourself as a carer and a peer support line; Maggie's centres are open to family and friends as well as patients." },
];

// ---------------------------------------------------------------- supplements onto records other files own
/**
 * Supplements (Spike.supplements, applied by applySpikeSupplements): each attaches `colorectal` to a side-effect,
 * procedure or support record another file owns, with the sourced colorectal-specific note and the patient pages it
 * was read from. A supplement never creates a record, so a missing id fails the build rather than inventing one.
 */
const supplements: SpikeSupplement[] = [
  { id: "stoma", cancers: [CANCER], links: [BCUK_STOMA, NHS_COLOSTOMY_WHAT, NHS_COLOSTOMY_RECOVERY, NHS_COLOSTOMY_COMPLICATIONS, CRUK_STOMA, COLOSTOMY_UK_MANAGING, NG151],
    notes: [
      "Bowel cancer: Bowel Cancer UK says a stoma can be reversible (formed to let the bowel heal after surgery) or permanent (formed when there is not enough bowel left to join to the anus, or the two ends cannot be joined), and that the surgeon may not know for certain until the operation has started. A colostomy is formed from the large bowel, usually on the left, and the output is more solid; an ileostomy is formed from the small bowel and the output is looser.",
      "NICE NG151 says to advise people of the likelihood of having a stoma, why it might be necessary and for how long it might be needed, and that if relevant a trained stoma professional should provide information on the care and management of stomas and on learning to live with a stoma.",
      "The NHS says it usually takes around 8 weeks to recover from a colostomy, to avoid strenuous activity or heavy lifting for 8 weeks while the tummy muscles heal, and that with a permanent colostomy the GP gives a prescription for stoma bags free on the NHS while a temporary one may have to be paid for.",
    ] },
  { id: "colectomy", cancers: [CANCER], links: [MAC_COLON_SURGERY, NG151, MAC_PREP_SURGERY, BCUK_PREHAB],
    notes: ["Colon cancer: NICE NG151 recommends laparoscopic resection as an alternative to open resection when both techniques are suitable, and says to consider preoperative systemic anticancer therapy for people with cT4 colon cancer. Bowel Cancer UK says prehabilitation before the operation can reduce anxiety, improve fitness and shorten the stay in hospital, and that it may be offered as part of an enhanced recovery programme."] },
  { id: "total-mesorectal-excision", cancers: [CANCER], links: [NG151, MAC_RECTAL_SURGERY, BCUK_STOMA],
    notes: ["Rectal cancer: NICE NG151's table for early rectal cancer compares transanal excision, endoscopic submucosal dissection and total mesorectal excision on the points a patient weighs, namely whether bowel is resected (with more impact on sexual and bowel function), whether a stoma is possible, the usual hospital stay of 5 to 7 days against 1 to 2, and external scarring. Its listed complications include adhesions, anastomotic leak, anastomotic stricture, bleeding, incisional hernia, injury to neighbouring structures, pelvic abscess and urinary retention. NICE also says hospitals performing major resection for rectal cancer should perform at least 10 each year and individual surgeons at least 5."] },
  { id: "organ-preservation", cancers: [CANCER], links: [NG151, MAC_CHEMORAD_RECTAL],
    notes: ["Rectal cancer (watch and wait): NICE NG151 says to inform people with a complete clinical and radiological response to neoadjuvant treatment who wish to defer surgery that there is a risk of recurrence and that there are no prognostic factors to guide selection for deferral, and that for those who choose to defer, teams should encourage participation in a clinical trial and ensure data is collected via a national registry."] },
  { id: "total-neoadjuvant-therapy", cancers: [CANCER], links: [NG151, MAC_CHEMORAD_RECTAL],
    notes: ["Rectal cancer: NICE NG151 says to offer preoperative radiotherapy or chemoradiotherapy to people with rectal cancer that is cT1 to T2 with node involvement, or cT3 to T4 with any node status, and not to offer preoperative radiotherapy for early rectal cancer (cT1 to T2, cN0, M0) outside a clinical trial. Macmillan explains chemoradiation for rectal cancer as radiotherapy with chemotherapy tablets or a drip to make the radiotherapy work better."] },
  { id: "hepatectomy", cancers: [CANCER], links: [NG151, BCUK_ADVANCED, MAC_ADVANCED_BOWEL],
    notes: ["Colorectal liver metastases: NICE NG151 says to consider resection, either simultaneous or sequential, after discussion by a multidisciplinary team with expertise in resection of disease in all involved sites; to consider perioperative systemic anticancer therapy if liver resection is a suitable treatment; and to consider chemotherapy with local ablative techniques for liver metastases that are unsuitable for resection after discussion by a specialist multidisciplinary team."] },
  { id: "thermal-ablation", cancers: [CANCER], links: [NG151],
    notes: ["Colorectal metastases: NICE NG151 says to consider chemotherapy with local ablative techniques for colorectal liver metastases unsuitable for liver resection, and to consider metastasectomy, ablation or stereotactic body radiation therapy for lung metastases suitable for local treatment after discussion by a multidisciplinary team that includes a thoracic surgeon and a specialist in non-surgical ablation."] },
  { id: "peripheral-neuropathy", cancers: [CANCER], links: [MAC_OXALIPLATIN, BCUK_LATE, NG151],
    notes: [
      "Oxaliplatin (in FOLFOX and CAPOX) is the main cause in bowel cancer. Macmillan says the numbness, tingling or pain in hands and feet is often made worse by cold during treatment, so keep warm, avoid iced drinks, take care opening the fridge and use gloves for frozen food; rarely oxaliplatin causes a spasm around the voicebox with difficulty swallowing or breathing in the first days after treatment, and the next doses may then be given over 4 to 6 hours.",
      "Bowel Cancer UK says symptoms can appear during the cycle and for up to two weeks afterwards, may get worse before they get better, and in some people last months or years, making writing, picking up small items and walking difficult. NICE NG151 asks teams to monitor prolonged sensory symptoms after platinum chemotherapy because they can be a sign that the dose needs reducing to minimise future permanent neuropathy.",
    ] },
  { id: "hand-foot-syndrome", cancers: [CANCER], links: [MAC_CAPECITABINE, BCUK_LATE],
    notes: ["Capecitabine (in CAPOX and as a single tablet after surgery) and infused fluorouracil can make the palms and soles sore, red, dry or peeling. Macmillan says to keep hands and feet cool by washing in cool water, to moisturise gently and regularly, and to contact the hospital on the 24-hour number if the skin around the nails becomes sore and swollen, which may be a sign of infection."] },
  { id: "rash-skin-toxicity", cancers: [CANCER], links: [MAC_CETUXIMAB, MAC_PANITUMUMAB],
    notes: ["Cetuximab and panitumumab (the EGFR antibodies used for RAS wild-type metastatic disease) cause an acne-like rash on the face, neck, chest and back, most likely to start in the first 2 or 3 weeks. Macmillan says to contact the hospital as soon as possible on the 24-hour number for any skin change, because creams, steroids or antibiotics may be needed and treatment may be paused; do not use products containing alcohol or anti-acne products unless prescribed, moisturise with unperfumed moisturisers, and use sun cream of at least SPF 30 with clothing and a hat. Blood magnesium and calcium are checked regularly because these drugs lower them."] },
  { id: "neutropenia", cancers: [CANCER], links: [MAC_FOLFOX, MAC_IRINOTECAN, CG151],
    notes: ["FOLFOX, CAPOX, FOLFIRI and irinotecan all lower white cells. Macmillan says to contact the hospital straight away on the 24-hour number for a temperature outside the range your team gave you, shivering, or feeling unwell even with a normal temperature; blood counts are checked before each cycle and treatment is delayed when they are low."] },
  { id: "febrile-neutropenia", cancers: [CANCER], links: [NHS_SEPSIS, MAC_SEPSIS, CG151],
    notes: ["Bowel cancer chemotherapy: the NHS says to call 999 or go to A&E for breathing very fast, confusion or slurred speech, blue, pale or blotchy skin, a very high or very low temperature, shivering, or a rash that does not fade when pressed. A stoma is a second route to dehydration and infection in this cancer, so fever with a high stoma output counts twice."] },
  { id: "mucositis", cancers: [CANCER], links: [MAC_FOLFOX, MAC_CAPECITABINE],
    notes: ["Fluorouracil, capecitabine and irinotecan can all cause a sore mouth and ulcers. Macmillan says to use a soft toothbrush morning, night and after meals, to avoid food and drink that irritate the mouth, and to ring the 24-hour number if soreness affects how much you can eat or drink or if there are blisters, ulcers or white patches."] },
  { id: "cancer-related-fatigue", cancers: [CANCER], links: [BCUK_FATIGUE, CRUK_LIVING, FABI_2020],
    notes: ["Bowel cancer: Bowel Cancer UK's sleep and fatigue page treats tiredness as a symptom to report rather than something to endure, because anaemia, poor sleep, low mood and the treatment itself are separate and separately treatable causes. Gentle activity, a routine and a conversation about anaemia are the first steps; the ESMO fatigue guideline puts exercise and psychological support ahead of stimulant drugs."] },
  { id: "late-effects", cancers: [CANCER], links: [BCUK_LATE, MAC_BOWEL_CHANGES, NG151],
    notes: ["Bowel cancer: Bowel Cancer UK lists hernia at the wound or around the stoma (avoid heavy lifting for up to three months, then ask about core exercises and a support garment) and oxaliplatin neuropathy among the effects that last beyond six months or start later. NICE NG151 asks teams to give information about short-term, long-term, permanent and late side effects including pain, altered bowel, urinary or sexual function, nerve damage and neuropathy, and mental and emotional changes including anxiety, depression, chemotherapy-related cognitive impairment and changes to self-perception and social identity."] },
  { id: "oncology-nutrition", cancers: [CANCER], links: [BCUK_DIET, CRUK_EATING, MAC_BOWEL_CHANGES, COLOSTOMY_UK_DIET],
    notes: ["Bowel cancer: Macmillan says to eat at regular times, to try several small meals rather than one or two large ones, to include high-protein foods to help healing, to follow a low-fibre diet for the first few days after surgery and to keep a diary of what you eat and how it affects you. Cancer Research UK says the foods most likely to cause problems are very high fibre fruit and vegetables, onions, brussels sprouts and cabbage, pulses, fizzy drinks, beer and lager, and very rich or fatty foods, and that a food can be tried again after a few weeks."] },
  { id: "prehabilitation", cancers: [CANCER], links: [BCUK_PREHAB, CRUK_PREHAB, MAC_PREP_SURGERY],
    notes: ["Before bowel cancer surgery: Bowel Cancer UK says prehabilitation aims to improve physical and emotional health before treatment and may involve a dietitian, a physiotherapist, an occupational therapist and a counsellor or psychologist, and that the evidence shows it reduces anxiety, improves fitness and can shorten the time in hospital. It may be offered as part of an enhanced recovery programme, which aims to help the bowel start working sooner after the operation."] },
  { id: "eras-perioperative-nutrition", cancers: [CANCER], links: [NG151, BCUK_PREHAB],
    notes: ["Bowel cancer: NICE NG151 says that if recovery protocols such as enhanced recovery after surgery are used, teams should explain to people what these involve and their value in improving recovery after surgery, and defines them as perioperative care pathways designed to promote early recovery by optimising health before surgery and maintaining health and functioning after it."] },
  { id: "palliative-care", cancers: [CANCER], links: [NHS_BOWEL_TREATMENT, BCUK_EOL],
    notes: ["Bowel cancer: the NHS says that if advanced bowel cancer cannot be cured you will be referred to a symptom control or palliative care team who help you manage symptoms, feel more comfortable and get other support for you and your loved ones. Bowel Cancer UK says palliative care may start when you are diagnosed with advanced bowel cancer or after treatment has stopped working, that its aim is to improve quality of life, and that you can choose to be cared for at home, in a hospice, in hospital or in a care home."] },
  { id: "germline-testing", cancers: [CANCER], links: [BCUK_LYNCH, BCUK_FAMILY_HISTORY, NHS_GENOMIC, NG151],
    notes: ["Bowel cancer: Bowel Cancer UK says Lynch syndrome is estimated to cause around 3 percent of bowel cancer cases in the UK each year, that testing should be offered at diagnosis because the condition can affect treatment options, and that if a person has it there is a 50 percent chance their children, brothers and sisters do too, so relatives should be offered the same test (cascade testing). NICE NG151 says to consider aspirin daily for more than 2 years to reduce the risk of colorectal cancer in people with Lynch syndrome, an off-label use in January 2020 with a NICE patient decision aid to support the discussion."] },
  { id: "msi-mmr-testing", cancers: [CANCER], links: [MAC_CELL_TESTS, NG151, BCUK_LYNCH],
    notes: ["Bowel cancer: the mismatch repair or microsatellite instability result does three jobs at once. It opens the door to immunotherapy (NICE NG151 recommends nivolumab with ipilimumab and pembrolizumab for untreated metastatic disease that is MSI-high or mismatch repair deficient), it starts the Lynch syndrome pathway when repair proteins are lost, and it feeds the conversation about chemotherapy after surgery. NICE NG151 separately requires RAS and BRAF V600E testing in everyone with metastatic disease suitable for systemic treatment."] },
  { id: "psycho-oncology", cancers: [CANCER], links: [CRUK_COPING, BCUK_BODY_SEX, MAGGIES, NG151],
    notes: ["Bowel cancer: NICE NG151 names mental and emotional changes, including anxiety, depression, chemotherapy-related cognitive impairment and changes to self-perception and social identity, among the effects teams should give information about, and defines social identity as changes to a person's concept of themselves as a result of the cancer or its long-term effects. Bowel Cancer UK says talking about how you feel helps, and that a stoma care nurse specialist, a counsellor or the GP are all reasonable first calls."] },
  { id: "peer-support-groups", cancers: [CANCER], links: [BCUK_CARERS, CRUK_COPING, MAGGIES],
    notes: ["Bowel cancer: Bowel Cancer UK runs online communities, a forum, an Ask the Nurse service and a stoma support group; Cancer Research UK runs Cancer Chat and a freephone nurse line; Maggie's centres are free, need no appointment and are open to family and friends as well as patients."] },
  { id: "fertility-preservation", cancers: [CANCER], links: [BCUK_FERTILITY],
    notes: ["Bowel cancer: Bowel Cancer UK says some treatments affect fertility and the team should discuss the risk at diagnosis, that radiotherapy to the pelvis will often cause infertility and early menopause and will affect the uterus so that pregnancy is not possible even with fertility treatment, that chemotherapy can cause temporary or permanent infertility depending on the drugs and doses, and that both men and women should use contraception during radiotherapy and chemotherapy and for about a year afterwards."] },
  { id: "financial-toxicity", cancers: [CANCER], links: [BCUK_WORK, COLOSTOMY_UK_WORK],
    notes: ["Bowel cancer in the UK: Bowel Cancer UK says that from diagnosis you are protected from discrimination at work by the Equality Act 2010 (the Disability Discrimination Act 1995 in Northern Ireland), that your employer must make reasonable adjustments such as different or part-time hours, time off for appointments or changed duties, that a phased return is a normal request, and that the Access to Work schemes can fund equipment and sometimes taxis. It lists the benefits that may apply, including Personal Independence Payment, Adult Disability Payment in Scotland, Attendance Allowance and Carer's Allowance."] },
  { id: "survivorship-care-plan", cancers: [CANCER], links: [NG151, BCUK_LATE, MAC_BOWEL_CHANGES],
    notes: ["Bowel cancer: NICE NG151 says that for people who have had potentially curative surgical treatment for non-metastatic colorectal cancer, teams should offer follow-up for detection of local recurrence and distant metastases for the first 3 years, including serum carcinoembryonic antigen and CT of the chest, abdomen and pelvis. It also asks teams to help people prepare for discharge with advice on adapting physical activity, on diet including foods that contribute to diarrhoea, flatulence, incontinence and difficulty emptying the bowels, on stopping smoking, on how long recovery might take and on how, when and where to seek help if side effects become problematic."] },
  { id: "cea-surveillance-colorectal", cancers: [CANCER], links: [NG151],
    notes: ["NICE NG151 places the CEA blood test inside the same recommendation as the CT scan: follow-up for the first 3 years after potentially curative surgery for non-metastatic colorectal cancer should include serum carcinoembryonic antigen and CT of the chest, abdomen and pelvis."] },
  { id: "colonoscopy", cancers: [CANCER], links: [BCUK_LYNCH, NHS_BOWEL_TESTS],
    notes: ["Bowel cancer and Lynch syndrome: Bowel Cancer UK says people with Lynch syndrome should be in a surveillance programme with regular colonoscopy every 18 months to two years, which can reduce the chance of dying from bowel cancer by as much as 72 percent, and that waits for these routine appointments are often too long."] },
  { id: "multidisciplinary-tumour-board", cancers: [CANCER], links: [MAC_MDT_BOWEL, NG151],
    notes: ["Bowel cancer: Macmillan describes the bowel cancer multidisciplinary team, and NICE NG151 requires multidisciplinary discussion at the points where the answer changes a life: resection of liver metastases by a team with expertise in resection of disease in all involved sites, lung metastases with a thoracic surgeon and a specialist in non-surgical ablation, peritoneal disease with referral to a nationally commissioned specialist centre, and locally advanced or recurrent rectal cancer with referral for exenterative surgery."] },
];

